INSERT INTO public.advanced_assessment_evidence (evidence_version, topic_tags, title, publisher, source_type, url, summary, verification_status, citation_code, pmid, doi, publication_year, verification_note) VALUES
  ('2026.2', ARRAY['breakouts_acne','benzoyl_peroxide','retinoid','bha_exfoliant','azelaic_acid','texture_congestion']::text[], 'Guidelines of care for the management of acne vulgaris', 'Journal of the American Academy of Dermatology', 'clinical_guideline', 'https://doi.org/10.1016/j.jaad.2023.12.017', 'American Academy of Dermatology GRADE-based guideline (2024). Strong recommendations for benzoyl peroxide and topical retinoids; conditional recommendations for topical salicylic acid and azelaic acid. Combining topical therapies with multiple mechanisms of action is a good-practice statement.', 'verified', 'C1', '38300170', '10.1016/j.jaad.2023.12.017', 2024, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['photoprotection','sunscreen','fine_lines_aging','fine_lines_wrinkles','reduced_signs_of_aging']::text[], 'Sunscreen and prevention of skin aging: a randomized trial', 'Annals of Internal Medicine', 'peer_reviewed', 'https://doi.org/10.7326/0003-4819-158-11-201306040-00002', 'Community-based randomised controlled trial in Australian adults: regular daily sunscreen use, compared with discretionary use, retarded skin ageing as measured by photoageing. Conducted in a predominantly lighter-skinned population.', 'verified', 'C2', '23732711', '10.7326/0003-4819-158-11-201306040-00002', 2013, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['photoprotection','sunscreen','uneven_tone_pigmentation','pigmentation_patches','melasma','skin_of_colour']::text[], 'Sunscreens part 1: Mechanisms and efficacy', 'Journal of the American Academy of Dermatology', 'peer_reviewed', 'https://doi.org/10.1016/j.jaad.2024.02.065', 'Review of sunscreen filters and additives and their efficacy against sunburn, photoageing and pigmentary disorders, including considerations for product selection in people with skin of colour.', 'verified', 'C3', '38772426', '10.1016/j.jaad.2024.02.065', 2024, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['photoprotection','visible_light','iron_oxide','melasma','pih','uneven_tone_pigmentation','pigmentation_patches','skin_of_colour']::text[], 'Photoprotection beyond ultraviolet radiation: A review of tinted sunscreens', 'Journal of the American Academy of Dermatology', 'peer_reviewed', 'https://doi.org/10.1016/j.jaad.2020.04.079', 'Visible light can induce pigmentation in darker skin; broad-spectrum (UV) sunscreens do not adequately protect against it. Tinted sunscreens containing iron oxides and pigmentary titanium dioxide protect against visible light and are beneficial for hyperpigmentation disorders such as melasma and post-inflammatory hyperpigmentation.', 'verified', 'C4', '32335182', '10.1016/j.jaad.2020.04.079', 2020, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['photoprotection','visible_light','iron_oxide','skin_of_colour','pih']::text[], 'Enhancing Photoprotection: Assessing Visible Light Photoprotection in Tinted Inorganic Sunscreens', 'Photodermatology, Photoimmunology & Photomedicine', 'peer_reviewed', 'https://doi.org/10.1111/phpp.70104', 'Study in 12 adults with Fitzpatrick skin types IV–VI: a zinc-based tinted (iron oxide) sunscreen with antioxidants reduced visible-light/UVA1-induced pigmentation and erythema versus zinc oxide alone; not all tinted mineral formulas performed equally. Small, manufacturer-funded study.', 'verified', 'C5', '42310896', '10.1111/phpp.70104', 2026, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['pih','scarring_marks','uneven_tone_pigmentation','skin_of_colour','azelaic_acid','retinoid','tranexamic_acid','photoprotection']::text[], 'Post-inflammatory Hyperpigmentation in Skin of Color: Emerging Therapies and Treatment Algorithms', 'Cureus', 'peer_reviewed', 'https://doi.org/10.7759/cureus.107234', 'Review (2015–2025 literature) of PIH treatment with a focus on skin of colour: topical retinoids, azelaic acid, cysteamine and tranexamic acid alongside photoprotection are first-line options; chemical peels and lasers need caution in darker skin; gentle skincare and sun protection come first.', 'verified', 'C6', '42153065', '10.7759/cureus.107234', 2026, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['azelaic_acid','tranexamic_acid','pih','scarring_marks','breakouts_acne']::text[], 'A comparative study of 20% azelaic acid cream versus 5% tranexamic acid solution for the treatment of postinflammatory hyperpigmentation in patients with acne vulgaris', 'Journal of Research in Medical Sciences', 'peer_reviewed', 'https://doi.org/10.4103/jrms.jrms_443_22', 'Single-blinded randomised trial (60 participants, 12 weeks): both 20% azelaic acid cream and 5% tranexamic acid solution improved acne-related PIH comparably; tranexamic acid had fewer side effects in the first month.', 'verified', 'C7', '37213446', '10.4103/jrms.jrms_443_22', 2023, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['niacinamide','fine_lines_aging','fine_lines_wrinkles','uneven_tone_pigmentation','redness']::text[], 'Niacinamide: A B vitamin that improves aging facial skin appearance', 'Dermatologic Surgery', 'peer_reviewed', 'https://doi.org/10.1111/j.1524-4725.2005.31732', 'Double-blind, split-face randomised study (50 white women, 12 weeks): 5% topical niacinamide reduced fine lines, hyperpigmented spots, red blotchiness and sallowness and improved elasticity versus vehicle. Evidence from a lighter-skinned cohort only.', 'verified', 'C8', '16029679', '10.1111/j.1524-4725.2005.31732', 2005, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['niacinamide','uneven_tone_pigmentation','pigmentation_patches','fine_lines_aging','redness']::text[], 'Topical niacinamide reduces yellowing, wrinkling, red blotchiness, and hyperpigmented spots in aging facial skin', 'International Journal of Cosmetic Science', 'peer_reviewed', 'https://doi.org/10.1111/j.1467-2494.2004.00228.x', 'Double-blind, placebo-controlled split-face study (50 Caucasian women aged 40–60, 12 weeks): a moisturiser with 5% niacinamide was well tolerated and improved fine lines, hyperpigmented spots, texture, red blotchiness and sallowness versus the same moisturiser without it. Lighter-skinned cohort only.', 'verified', 'C9', '18492135', '10.1111/j.1467-2494.2004.00228.x', 2004, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['retinoid','fine_lines_aging','fine_lines_wrinkles','reduced_signs_of_aging']::text[], 'Improvement of photoaged facial skin in middle-aged Japanese females by topical retinol (vitamin A alcohol): a vehicle-controlled, double-blind study', 'Journal of Dermatological Treatment', 'peer_reviewed', 'https://doi.org/10.1080/09546630902973987', 'Randomised, vehicle-controlled split-face study: 0.075% retinol cream for 26 weeks improved fine and deep wrinkling versus vehicle; a 0.04% retinol cream caused minimal irritation. Suggests low-strength retinol is suitable for gradual daily use.', 'verified', 'C10', '20078381', '10.1080/09546630902973987', 2009, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['tranexamic_acid','melasma','pigmentation_patches','uneven_tone_pigmentation']::text[], 'Tranexamic acid as a therapeutic option for melasma management: meta-analysis and systematic review of randomized controlled trials', 'Journal of Dermatological Treatment', 'peer_reviewed', 'https://doi.org/10.1080/09546634.2024.2361106', 'Meta-analysis of randomised controlled trials evaluating tranexamic acid for melasma, including adverse effects and comparisons with other melasma treatments. Includes non-topical routes; only topical cosmetic use is relevant to SKYNN guidance.', 'verified', 'C11', '38843906', '10.1080/09546634.2024.2361106', 2024, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['razor_bumps','pfb','skin_of_colour','pih']::text[], 'Review of treatments for pseudofolliculitis barbae', 'Clinical and Experimental Dermatology', 'peer_reviewed', 'https://doi.org/10.1093/ced/llad075', 'Review of the epidemiology, presentation and evidence-based management of pseudofolliculitis barbae (razor bumps), a chronic inflammatory condition of the beard area that predominantly affects people with skin of colour.', 'verified', 'C12', '36840647', '10.1093/ced/llad075', 2023, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
  ('2026.2', ARRAY['skin_barrier','dryness_dehydration','redness_sensitivity','moisturiser','ceramides']::text[], 'The Skin Barrier and Moisturization: Function, Disruption, and Mechanisms of Repair', 'Skin Pharmacology and Physiology', 'peer_reviewed', 'https://doi.org/10.1159/000534136', 'Review of skin barrier function, how it is disrupted, and how moisturisation supports repair; moisturisation is recommended as an initial measure where the barrier is compromised.', 'verified', 'C13', '37717558', '10.1159/000534136', 2023, 'PMID/DOI resolved live against PubMed on 2026-09-23; summary written from the PubMed abstract.'),
